/**
 * The most one page of sales weighs as JSON (lib/api-sales.ts), derived from the cuts the code makes: every text
 * is cut to its limit with control characters and lone surrogates dropped, so each unit left is at most
 * SALES_TEXT_BYTES bytes (a CJK character is three; a quote or a backslash, escaped, two). A sale holds its
 * checkout id, its product (an id and a title as the checkout writes it), its option, a bundle of
 * MAX_BUNDLE_ITEMS products, BUMP_KEYS.length checked boxes each with a bundle of its own, the first of them twice
 * (order_bump and order_bumps), the buyer's address and name, four utm tags and a site, two times; every listed product has
 * a catalog title (MAX_TITLE_LENGTH). SALES_KEY_BYTES is each object's keys and punctuation, with the kind, the
 * numbers, the time and the flags: tests/api-sales.test.ts holds a page built at these limits under the figure.
 */
const SALES_TEXT_BYTES = 3;
const SALES_KEY_BYTES = { sale: 600, entry: 32, bump: 50, page: 300 };
/** A time as the answer writes it ("2026-09-20T09:41:10.000Z"): opened_at and paid_at. */
const SALES_TIME_BYTES = 24;
const SALES_ENTRY_BYTES = SALES_KEY_BYTES.entry + SALES_SAFE_ID_LENGTH + SALES_LISTING_TITLE * SALES_TEXT_BYTES;
const SALES_BUMP_BYTES = SALES_KEY_BYTES.bump + SALES_ENTRY_BYTES + MAX_BUNDLE_ITEMS * SALES_ENTRY_BYTES;
export const API_SALE_BYTES = SALES_KEY_BYTES.sale + SALES_ID_LENGTH
  + SALES_SAFE_ID_LENGTH + SALE_TEXT_LIMITS.title * SALES_TEXT_BYTES + SALES_SAFE_ID_LENGTH
  + MAX_BUNDLE_ITEMS * SALES_ENTRY_BYTES + (BUMP_KEYS.length + 1) * SALES_BUMP_BYTES
  + (SALE_TEXT_LIMITS.email + SALE_TEXT_LIMITS.name + 4 * SALE_TEXT_LIMITS.utm + SALE_TEXT_LIMITS.site) * SALES_TEXT_BYTES
  + 2 * SALES_TIME_BYTES;
export const API_SALES_ANSWER_BYTES = SALES_KEY_BYTES.page + SALES_ID_LENGTH + SALES_PAGE * (API_SALE_BYTES + 1);
/**
 * One page of sales read through the API (GET /api/v1/sales, lib/api-sales.ts), at the most: Stripe waited on for
 * its whole ceiling (STRIPE_TIMEOUT_MS) on top of the request's own light seconds, at 2 GB; a CPU second through up
 * to SALES_PAGE expanded checkouts and the answer; the key, the store and the figure taken twice, and one read of up
 * to SALES_TITLE_IDS listings at 16 KB each; and an answer of up to API_SALES_ANSWER_BYTES on to the browser. It is
 * taken as API_SALES_UNITS API requests, which cost at least this with room (tests/plan-cost-registry.test.ts), so
 * it stays inside the plan's rest-api figure.
 */
export const API_SALES_READ = CALL + 1 * CPU_SECOND + (STRIPE_TIMEOUT_MS / 1000 + SHAPES.light.seconds) * MEMORY_SECOND
  + (20 + 2 * TAKE_COMMANDS + 1) * COMMAND + (20_000 + SALES_TITLE_IDS * 16_384) * DB_BYTE + API_SALES_ANSWER_BYTES * ORIGIN_PER_BYTE;

/** Additional Path growth reading: at most eight 256 KB products, three 80 KB campaigns, three bounded reviews and their indexes. Fifty commands and 3 MB include admission overhead; reserved separately before reading. No provider call. */
export const PATH_GROWTH_READ = request("write", 50, 3_000_000);

/**
 * One reading of a store's own plan invoices (601 [KB22] U5, lib/plan-invoices.ts), past the page's own
 * STUDIO_PAGE_UNITS: one GET of Stripe's invoice list waited on for its whole ceiling (STRIPE_TIMEOUT_MS) at 2 GB,
 * a CPU second and four megabytes of reading (PLAN_INVOICES_SHOWN invoices with their lines; the body is not capped
 * in bytes, but its download and parse run inside the same STRIPE_TIMEOUT_MS, lib/billing.ts onPlatform), and 64 KB
 * more sent on to the browser. Taken as one of the store's ESSENTIAL_PER_DAY requests of the day, only while fewer
 * than PLAN_INVOICES_PER_DAY were taken, before Stripe is asked (the counter countStudio keeps for "billing"), each priced in the studio line as a
 * heavy request and in platform-subscription-search as two Stripe GETs; tests/plan-cost-registry.test.ts holds this
 * under that, with room, so it adds nothing to either line. The wait is priced at the dearer of the model's
 * memory second and PLATFORM_SUBSCRIPTION_SEARCH's highest regional
 * rate; Stripe's tariff for the GET stays unknown, as there: not certified zero.
 */
export const PLAN_INVOICES_READ = CALL + 1 * CPU_SECOND + Math.max((STRIPE_TIMEOUT_MS / 1000) * MEMORY_SECOND, PLATFORM_SUBSCRIPTION_SEARCH.memoryUsdPerGet) + perMegabyte(4_000_000) + 65_536 * ORIGIN_PER_BYTE;

app/api/store/page/route.ts.content:
import { fastMoneyOnPage } from "@/lib/terms-check-rules";
import { pageWords } from "@/lib/page-translate";
import type { NextRequest } from "next/server";
import { StoreFullError, imageFolder, isFree, setProductPage } from "@/lib/store";
import { productIdFor, readListing } from "@/lib/catalog";
import { guardStoreWrite, text } from "@/lib/store-request";
import { EMPTY_PAGE, MAX_BLOCKS, type SalesPage, copyOfPage, declareMeasure, oversized, pageProblem, parsePage, picturePaths } from "@/lib/sales-page";
import { countStudio, jsonAccess, refusedJson } from "@/lib/studio-route";
import { lockedFor } from "@/lib/two-step";
import { claimNewPictures, readPage, releasePictures, writePage } from "@/lib/sales-page-store";
import { del } from "@/lib/blob";
import { imagePaths, ownsImagePath } from "@/lib/product-image";
import { pictureChecker } from "@/lib/picture-check";

/**
 * Thirty full blocks as JSON, twice — a page and a second version tested
 * against it — with room to spare; each is held to MAX_PAGE_BYTES.
 */
const MAX_BODY_BYTES = 420_000;

/** A page read whose answer is not known: refused before anything is written (lib/studio-messages.ts page_unread). */
const unread = () => Response.json({ ok: false, error: "page_unread" }, { status: 503, headers: { "Cache-Control": "private, no-store" } });

/**
 * Saves a product's page of blocks (lib/sales-page.ts), or clears it.
 *
 * `{ id, page: { blocks, seoTitle, seoDescription, next, test, variant } }`, or
 * `{ id, page: null }` for the plain page again. Every rule the product's
 * page applies is applied here first, and a page that would be saved
 * differently from how it was sent is refused with the reason, so the
 * studio never says "saved" about something it did not save.
 */
export async function POST(request: NextRequest) {
  // A product's page is part of the product (lib/team-roles.ts): owner, Admin, Editor.
  const guarded = await guardStoreWrite(request, "products", MAX_BODY_BYTES);
  if (!guarded.ok) return guarded.response;
  const body = guarded.body;
  const id = text(body.id, 40);
  if (!id || !("page" in body)) return Response.json({ ok: false, error: "unknown" }, { status: 400 });

  const store = guarded.store;
  const product = await readListing(store, id);
  if (!product) return Response.json({ ok: false, error: "unknown" }, { status: 400 });

  const raw = body.page && typeof body.page === "object" ? (body.page as Record<string, unknown>) : null;
  const page = raw ? parsePage(raw) : { ...EMPTY_PAGE, blocks: [] };
  if (raw) {
    if (Array.isArray(raw.blocks) && raw.blocks.length > MAX_BLOCKS) return Response.json({ ok: false, error: "too_many" }, { status: 400 });
    const problem = pageProblem(raw, page);
    if (problem) return Response.json({ ok: false, error: problem }, { status: 400 });
    // A form is asked on the store's own pages, where it can lead a funnel on; a product's page has its own checkout.
    if (page.blocks.some((block) => block.kind === "form")) return Response.json({ ok: false, error: "kind" }, { status: 400 });
    // A booking block is kept and drawn but not offered yet (552 [BB1] unit 1): nothing saves one, in either version,
    // until its picker and its call chooser exist, so a hand-made request cannot put any id on a page.
    if ([...page.blocks, ...(page.variant?.blocks ?? [])].some((block) => block.kind === "booking")) {
      return Response.json({ ok: false, error: "kind" }, { status: 400 });
    }
    if (oversized(page)) return Response.json({ ok: false, error: "too_big" }, { status: 400 });
    // What is shown after a free sign-up is another product of this store,
    // one that costs money; a paid product's page shows nothing after.
    const sentNext = typeof raw.next === "string" && raw.next ? raw.next : null;
    if (sentNext) {
      const next = await readListing(store, sentNext);
      if (!isFree(product) || !next || next.id === product.id || isFree(next)) {
        return Response.json({ ok: false, error: "next" }, { status: 400 });
      }
    }
  }

  // A page is on the store with its product: what the Terms forbid is refused while the product is published
  // (567 [GD1] (d), unit 2), with the passage, why and the fix; a draft's page may be saved, and is checked when
  // the product is published. A product that cannot be read was refused above.
  if (product.hidden !== true) {
    const refused = fastMoneyOnPage(pageWords(page));
    if (refused) return Response.json({ ok: false, error: "fast_money", passage: refused }, { status: 409 });
  }

  const has = page.blocks.length > 0 || page.seoTitle !== "" || page.seoDescription !== "" || page.next !== null;
  try {
    // The pictures on the page (lib/sales-page.ts, PicturesBlock). What the
    // browser says it uploaded is never taken at face value: each new one
    // has to be a file in this store's own picture folder that really is a
    // picture, not the product's own picture under another name, and not
    // one another product's page is already showing.
    // A page whose read is not known is never taken for an empty one: nothing is claimed, released or written from it.
    let stored: SalesPage | null = null;
    if (store.statsId && product.page) {
      try {
        stored = await readPage(store.statsId, id);
      } catch (error) {
        console.error("reading a product page before saving it failed", error);
        return unread();
      }
    }
    const before = stored ? picturePaths(stored) : [];
    const shown = picturePaths(page);
    // A picture taken off the page is deleted for good: not from a session let in without its second step (lib/two-step.ts).
    if (before.some((path) => !shown.includes(path)) && (await lockedFor(request, "products", "replace"))) return refusedJson("locked");
    const fresh = shown.filter((path) => !before.includes(path));
    if (fresh.length > 0) {
      if (!store.statsId) return Response.json({ ok: false, error: "server_error" }, { status: 500 });
      const folder = await imageFolder(guarded.ref);
      const own = new Set(imagePaths(product.image));
      if (fresh.some((path) => !ownsImagePath(path, folder) || own.has(path))) {
        return Response.json({ ok: false, error: "pictures" }, { status: 400 });
      }
      // Each new one fresh from the picture door or already this page's, never another record's picture from the
      // shared folder, so taking it off later deletes only this page's own (lib/sales-page-store.ts, claimNewPictures).
      // Only those this save takes from the door are checked in the file store, and once (MR audit gap 1): one taken
      // by an earlier save was checked then, so a save tried again never asks Blob about the same picture twice.
      if (!(await claimNewPictures(store.statsId, id, fresh, pictureChecker(async (units) => (await countStudio(store, "products", units)).ok)))) {
        return Response.json({ ok: false, error: "pictures" }, { status: 400 });
      }
    }

    const marked = await setProductPage(guarded.ref, id, has);
    if (!marked.ok) return Response.json({ ok: false, error: marked.reason }, { status: 400 });
    if (!marked.store.statsId) return Response.json({ ok: false, error: "server_error" }, { status: 500 });
    // A running test declares, once, the measure it is decided by (lib/headline-test-rules.ts, rule 2).
    const saved = declareMeasure(page, stored, isFree(product) ? "checkouts" : "money");
    await writePage(marked.store.statsId, id, saved, marked.store);
    // A picture taken off the page is deleted, best effort and only after the
    // page that no longer shows it is written.
    const gone = await releasePictures(marked.store.statsId, id, before.filter((path) => !shown.includes(path))).catch(() => [] as string[]);
    if (gone.length > 0) {
      await del(gone).catch((error: unknown) => console.error("could not delete pictures taken off a page", error));
    }
    // The page as it was kept, so the editor shows exactly that without starting over.
    return Response.json({ ok: true, blocks: saved.blocks.length, page: saved });
  } catch (error) {
    if (error instanceof StoreFullError) return Response.json({ ok: false, error: "store_full" }, { status: 409 });
    console.error("saving a product page failed", error);
    return Response.json({ ok: false, error: "server_error" }, { status: 500 });
  }
}

/**
 * Another product's page of this store, to start a page from: `?id=<product>`.
 * Its blocks with fresh ids and without its pictures (lib/sales-page.ts,
 * copyOfPage); nothing is saved here.
 */
export async function GET(request: NextRequest) {
  const access = await jsonAccess(request, "products");
  if (access instanceof Response) return access;
  const id = (request.nextUrl.searchParams.get("id") ?? "").slice(0, 40);
  const store = access.store;
  if (!store || !id || productIdFor(store, id) !== id) return Response.json({ ok: false, error: "unknown" }, { status: 404 });
  try {
    const copy = copyOfPage(await readPage(store.statsId, id));
    return Response.json({ ok: true, ...copy }, { headers: { "Cache-Control": "private, no-store" } });
  } catch (error) {
    // Never a copy started from an empty page that was not.
    console.error("reading a page to copy failed", error);
    return unread();
  }
}

app/api/store/site-page/route.ts.content:
import { randomBytes } from "node:crypto";
import type { NextRequest } from "next/server";
import { StoreFullError, imageFolder, setSitePages } from "@/lib/store";
import { guardStoreWrite, text } from "@/lib/store-request";
import { countStudio, refusedJson } from "@/lib/studio-route";
import { lockedFor } from "@/lib/two-step";
import { MAX_BLOCKS, emptyBlock, oversized, pageProblem, parsePage, picturePaths, type PageBlock } from "@/lib/sales-page";
import { claimNewPictures, dropPage, picturesOfFailedDrop, readPage, releasePictures, writePage } from "@/lib/sales-page-store";
import { del } from "@/lib/blob";
import { ownsImagePath } from "@/lib/product-image";
import { pictureChecker } from "@/lib/picture-check";
import { hasPlaceholder } from "@/lib/mail-body";
import { MAX_SITE_PAGES, SITE_KINDS, SITE_PAGE_ID, SITE_STARTERS, type SitePage, outFrom, siteKey, siteTitle, slugFrom, slugProblem } from "@/lib/site-page-rules";

/** Thirty full blocks as JSON, with room to spare; a page is held to MAX_PAGE_BYTES. */
const MAX_BODY_BYTES = 200_000;

const refuse = (error: string, status = 400) => Response.json({ ok: false, error }, { status });

/**
 * A store's own pages (lib/site-page-rules.ts): part of the public page, so
 * what the "page" role may change (lib/team-roles.ts).
 *
 *   { action: "add", title, slug?, starter? }   a new page, empty or from a starter's blocks
 *   { action: "meta", id, title, slug, nav, target }
 *   { action: "order", ids }
 *   { action: "remove", id }                    the page, its blocks and the pictures only it showed
 *   { action: "save", id, page }                its blocks, held to the rules a product's page is
 *
 * Every answer but "save" is the store's pages as they now are.
 */
export async function POST(request: NextRequest) {
  const guarded = await guardStoreWrite(request, "page", MAX_BODY_BYTES);
  if (!guarded.ok) return guarded.response;
  const { body, ref } = guarded;
  const store = guarded.store;
  const action = text(body.action, 10);
  const pages = store.sitePages;
  const id = text(body.id, 12);
  const found = pages.find((page) => page.id === id) ?? null;

  try {
    if (action === "add") {
      if (pages.length >= MAX_SITE_PAGES) return refuse("too_many");
      const starter = SITE_STARTERS.find((s) => s.slug === text(body.starter, 40)) ?? null;
      const title = siteTitle(body.title) || starter?.title || "";
      if (!title) return refuse("title");
      // The address asked for, or one made from the title, numbered if that one is taken.
      let slug = text(body.slug, 60) || starter?.slug || slugFrom(title);
      if (!text(body.slug, 60)) {
        const base = slug || "page";
        for (let n = 2; slugProblem(slug, pages) === "taken" && n < 50; n += 1) slug = `${base.slice(0, 36)}-${n}`;
      }
      const problem = slugProblem(slug, pages);
      if (problem) return refuse(problem);
      const page: SitePage = { id: randomBytes(5).toString("hex"), slug, title, nav: true, target: "", from: -1 };
      const saved = await setSitePages(ref, [...pages, page]);
      if (!saved.ok) return refuse(saved.reason);
      if (starter && saved.store.statsId) {
        const blocks: PageBlock[] = starter.kinds.map((kind) => emptyBlock(kind));
        const hero = blocks[0];
        if (hero?.kind === "hero") Object.assign(hero, { headline: title, media: "none" });
        await writePage(saved.store.statsId, siteKey(page.id), { ...parsePage({}), blocks, hidden: true }, saved.store);
      }
      return Response.json({ ok: true, pages: saved.store.sitePages, id: page.id });
    }

    if (action === "meta") {
      if (!found) return refuse("unknown", 404);
      const title = siteTitle(body.title);
      const slug = text(body.slug, 60);
      if (!title) return refuse("title");
      const problem = slugProblem(slug, pages, found.id);
      // A page keeps an address it already has, even one reserved since; only a new one is refused.
      if (problem && !(problem === "reserved" && slug === found.slug)) return refuse(problem);
      const next = pages.map((page) => (page.id === found.id ? { ...page, title, slug, nav: body.nav !== false, target: text(body.target, 40) } : page));
      const saved = await setSitePages(ref, next);
      return saved.ok ? Response.json({ ok: true, pages: saved.store.sitePages }) : refuse(saved.reason);
    }

    if (action === "order") {
      const ids = Array.isArray(body.ids) ? body.ids.map((x) => text(x, 12)) : [];
      if (ids.length !== pages.length || !pages.every((page) => ids.includes(page.id))) return refuse("unknown");
      const saved = await setSitePages(ref, ids.map((x) => pages.find((page) => page.id === x)));
      return saved.ok ? Response.json({ ok: true, pages: saved.store.sitePages }) : refuse(saved.reason);
    }

    if (action === "remove") {
      if (!found) return refuse("unknown", 404);
      const saved = await setSitePages(ref, pages.filter((page) => page.id !== found.id));
      if (!saved.ok) return refuse(saved.reason);
      const gone = await dropPage(saved.store.statsId, siteKey(found.id), saved.store).catch(picturesOfFailedDrop);
      if (gone.length) await del(gone).catch((error: unknown) => console.error("could not delete a removed page's pictures", error));
      return Response.json({ ok: true, pages: saved.store.sitePages });
    }

    if (action === "save") {
      if (!found || !SITE_PAGE_ID.test(found.id)) return refuse("unknown", 404);
      const raw = body.page && typeof body.page === "object" ? (body.page as Record<string, unknown>) : null;
      if (!raw) return refuse("invalid");
      if (Array.isArray(raw.blocks) && raw.blocks.length > MAX_BLOCKS) return refuse("too_many");
      // What a product's page tests (a second headline, a second version) and
      // shows after a sign-up has no place on a store's own page.
      const page = { ...parsePage({ ...raw, test: null, variant: null, next: null }), test: null, variant: null, next: null };
      const problem = pageProblem({ ...raw, variant: null }, page);
      if (problem) return refuse(problem);
      if (page.blocks.some((block) => !SITE_KINDS.includes(block.kind))) return refuse("kind");
      if (oversized(page)) return refuse("too_big");
      // A part left ⟦like this⟧ for the creator to write (lib/funnel-ai-rules.ts) is a
      // direction, never words shown to visitors: kept while hidden, refused once shown or scheduled.
      if (outFrom(page) !== -1 && hasPlaceholder(JSON.stringify(page.blocks))) return refuse("placeholder");
      if (!store.statsId) {
        // A store written before it had one is given its id with the list.
        const marked = await setSitePages(ref, pages);
        if (!marked.ok || !marked.store.statsId) return refuse("server_error", 500);
        store.statsId = marked.store.statsId;
      }
      const statsId = store.statsId;
      const key = siteKey(found.id);
      // Pictures: each new one a picture in this store's own folder, shown on no other page.
      // A page whose read is not known is never taken for an empty one: nothing is claimed, released or written from it.
      let held;
      try {
        held = await readPage(statsId, key);
      } catch (error) {
        console.error("reading a store page before saving it failed", error);
        return refuse("page_unread", 503);
      }
      const before = picturePaths(held);
      const shown = picturePaths(page);
      // A picture taken off the page is deleted for good: not from a session let in without its second step (lib/two-step.ts).
      if (before.some((path) => !shown.includes(path)) && (await lockedFor(request, "page", "replace"))) return refusedJson("locked");
      const fresh = shown.filter((path) => !before.includes(path));
      if (fresh.length) {
        const folder = await imageFolder(ref);
        if (fresh.some((path) => !ownsImagePath(path, folder))) return refuse("pictures");
        // Fresh from the picture door or already this page's, never a product's, a link's or another page's picture
        // from the shared folder (lib/sales-page-store.ts, claimNewPictures). Only those this save takes from the door
        // are checked in the file store, and once (MR audit gap 1).
        if (!(await claimNewPictures(statsId, key, fresh, pictureChecker(async (units) => (await countStudio(store, "page", units)).ok)))) return refuse("pictures");
      }
      await writePage(statsId, key, page, store);
      // When it is out, kept on the list so the menu reads nothing more (lib/site-page-rules.ts).
      const from = outFrom(page);
      if (from !== found.from) await setSitePages(ref, pages.map((p) => (p.id === found.id ? { ...p, from } : p)));
      const gone = await releasePictures(statsId, key, before.filter((path) => !shown.includes(path))).catch(() => [] as string[]);
      if (gone.length) await del(gone).catch((error: unknown) => console.error("could not delete pictures taken off a page", error));
      return Response.json({ ok: true, blocks: page.blocks.length, page });
    }

    return refuse("invalid");
  } catch (error) {
    if (error instanceof StoreFullError) return refuse("store_full", 409);
    console.error("changing a store's pages failed", error);
    return refuse("server_error", 500);
  }
}

tests/read-ceilings.test.ts.content:
/**
 * Three reads, each paid for before it reads anything (C4-4, 4 November 2026;
 * owner's rule MR: a ceiling before every spend, an unknown cost never zero).
 * The community search is Claude 3's (C4-6). What is checked, by behaviour,
 * with the in-memory database and a stand-in for Stripe:
 *
 *   - the private booking calendar answers a calendar app from the last good
 *     copy of its file and never spends the creator's studio requests; the
 *     file is made again only after a booking changed or once the copy is old,
 *     at most CALENDAR_BUILDS_PER_DAY a day, counted before Stripe is read;
 *     past that, and when Stripe fails, the copy is answered (never 503 while
 *     one exists); a feed asked more than CALENDAR_POLLS_PER_HOUR times an
 *     hour is asked to come back, reading nothing; the file keeps the events
 *     still to come first;
 *   - every unit of lib/read-ceilings.ts costs at least the worst it stands
 *     for, priced with the registry's own rates, and the calendar's own cost
 *     line is in the registry;
 *   - the totals page's reading of one store's numbers makes no more
 *     commands than TOTALS_STORE_SHAPE counts, and it takes its units first.
 *
 * (A product update's search for its buyers is counted in the studio's requests,
 *  lib/product-updates.ts updateReadUnits, held by tests/ledger-counted-callers.test.ts.)
 */
import { MAX_PAID_BYTES, PAYPAL_REFUNDS_READ } from "@/lib/paypal-sales";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import {
  CALENDAR_BUILDS_PER_DAY, CALENDAR_CREDITS_PER_DAY, CALENDAR_RETRIES_PER_DAY, CALENDAR_FILE_MAX_BYTES, CALENDAR_MAX_EVENTS, CALENDAR_POLLS_PER_HOUR, CALENDAR_REFRESH_SECONDS, CALENDAR_REFUSED_PER_HOUR,
  FeedGone, bookedCalendar, bookedCalendarFeed, calendarView, ensureFeedToken, forgetStoreCalendar, keptSlots, newFeedToken, storeIdForToken,
} from "@/lib/calendar-sync";
import { planReminders } from "@/lib/call-records";
import { GET as feedRoute } from "@/app/api/store/calendar/[token]/route";
import {
  CALENDAR_BUILD_PER_BOOKING, CALENDAR_BUILD_SHAPE, CALENDAR_POLL_SHAPE, CALENDAR_STRIPE_PAGES, LIFE_FILL_SHAPE, MEMBERS_READ_SHAPE, SALES_READ_SHAPE, STATS_READ_SHAPE,
  CALENDAR_REFUSED_SHAPE, ERASED_LOOKUP_BYTES, KEPT_READINGS_SHAPE, MEMBER_WORDS_NAMES, LIST_MADE_HEAD_READS, LIST_MADE_SHAPE, STORE_LOCK_TRIES, READING_COUNT_COMMANDS, STORE_READING_SHAPES, calendarBuildCommands,
} from "@/lib/read-ceilings";
import { TOP_BUYERS } from "@/lib/stats";
import { COMMENT_ADDRESSES, SHOWN_COMMENTS } from "@/lib/membership-numbers";
import { STORE_PAGE_SIZE } from "@/lib/catalog";
import { MAX_BUMPS } from "@/lib/product-extras";
import { createHash } from "node:crypto";
import { MAX_PRODUCTS } from "@/lib/catalog-rules";
import { HEAVY_READINGS_PER_DAY, STORE_READINGS_PER_DAY, ReadingsUsed, keptNumbers, readingsLeft, takeStoreReading } from "@/lib/store-readings";
