  redis.run(["DEL", `nl:cal:out:${owner.statsId}`]);
  await bookedCalendarFeed(owner, make, later + 7_200_000);
  is("a count found without an expiry gets one back", Number(redis.run(["TTL", buildsKey])) > 0, true);
