lib/picture-check.ts.content:
/**
 * Whether a file in the picture folder really is a picture.
 *
 * What a browser says it uploaded is never taken at face value
 * (app/api/store/image): the file store is asked how big the file really is
 * and what it says it is, and its first bytes have to be a JPEG's or a
 * WebP's. The same check, for a picture put on a product's page
 * (lib/sales-page.ts, PicturesBlock).
 */
import { BlobNotFoundError } from "@vercel/blob";
import { get, head } from "@/lib/blob";
import { dropTakenPictures, putBackOnce, returnToDoor } from "@/lib/picture-door";
import { IMAGE_CONTENT_TYPES, MAX_IMAGE_BYTES } from "@/lib/product-image";
import { sniffPhotoType } from "@/lib/store-photo";

/** The first bytes of a stored file, to see what it really is; "gone" when the store says there is no such file, null when its answer is not known. */
async function firstBytes(path: string): Promise<Uint8Array | "gone" | null> {
  const found = await get(path, { access: "private" });
  if (!found) return "gone";
  if (found.statusCode !== 200 || !found.stream) return null;
  const reader = found.stream.getReader();
  const chunks: Uint8Array[] = [];
  let length = 0;
  while (length < 16) {
    const { done, value } = await reader.read();
    if (done || !value) break;
    chunks.push(value);
    length += value.length;
  }
  await reader.cancel().catch(() => {});
  const bytes = new Uint8Array(length);
  let at = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, at);
    at += chunk.length;
  }
  return bytes;
}

/**
 * What the file store says of a file: "picture" when it is there, weighs no more than a picture may, and is a JPEG or
 * a WebP by its own bytes; "not" when the store answered and it is none of that (no such file, too big, other bytes);
 * "unknown" when the store did not answer (a timeout, a 5xx, a reset), never read as "not" (Claude 2 on #2843,
 * 6750890970; CX-123 rule 24).
 */
export async function pictureVerdict(path: string): Promise<"picture" | "not" | "unknown"> {
  let found: Awaited<ReturnType<typeof head>>;
  try {
    found = await head(path);
  } catch (error) {
    return error instanceof BlobNotFoundError ? "not" : "unknown";
  }
  if (found.size > MAX_IMAGE_BYTES) return "not";
  let bytes: Uint8Array | "gone" | null;
  try {
    bytes = await firstBytes(path);
  } catch {
    return "unknown";
  }
  if (bytes === "gone") return "not";
  if (bytes === null) return "unknown";
  const kind = sniffPhotoType(bytes);
  return kind !== null && (IMAGE_CONTENT_TYPES as readonly string[]).includes(kind) && kind === found.contentType ? "picture" : "not";
}

/** True when the file is there, weighs no more than a picture may, and is a JPEG or a WebP by its own bytes; anything not known is false. */
export async function isStoredPicture(path: string): Promise<boolean> {
  return (await pictureVerdict(path)) === "picture";
}

/** What the checks of a page save's pictures found: the pictures, and those whose check did not finish. */
export type PictureChecks = { good: string[]; unknown: string[] };

/**
 * The check of the pictures a page save has just taken from the picture door (lib/sales-page-store.ts,
 * claimNewPictures, before any is written down as the page's), each with when the door noted it. Each is checked in
 * the file store once (MR audit gap 1). Those that are not pictures are deleted through dropTakenPictures, so a file
 * stored before its note is kept: taken from the door by this very save, a file stored after it is nobody else's.
 *
 * A check that does not finish deletes nothing (Claude 2 on #2843, 6750890970): the picture is put back on the door,
 * once (returnToDoor, putBackOnce), so the creator's save tried again checks it again. That check made again is paid
 * for before it is made, one studio request each (`pay`), so the studio-blob line's bound still holds (a check costs
 * less than a studio request at its dearest); refused, nothing is checked and the picture is put back as it was. A
 * check made again that does not finish either leaves the file kept, out of the door: the creator uploads it again.
 */
export function pictureChecker(pay: (units: number) => Promise<boolean>): (taken: ReadonlyMap<string, number>) => Promise<PictureChecks> {
  return async (taken) => {
    const again = [...taken].filter(([, at]) => putBackOnce(at)).map(([path]) => path);
    const paid = again.length === 0 || (await pay(again.length).catch(() => false));
    const good: string[] = [];
    const bad: string[] = [];
    const unknown: string[] = [];
    const back: [string, number][] = [];
    for (const [path, at] of taken) {
      if (!paid && putBackOnce(at)) {
        unknown.push(path);
        back.push([path, at]);
        continue;
      }
      const verdict = await pictureVerdict(path);
      if (verdict === "picture") good.push(path);
      else if (verdict === "not") bad.push(path);
      else {
        unknown.push(path);
        if (!putBackOnce(at)) back.push([path, Math.floor(at) + 0.5]);
      }
    }
    if (bad.length) await dropTakenPictures(new Map(taken), bad);
    if (back.length) await returnToDoor(back);
    return { good, unknown };
  };
}

lib/picture-door.ts.content:
import { del, head } from "@/lib/blob";
import { isRedisConfigured, redisPipeline } from "@/lib/redis";
import { UnknownReplyError, countOf, repliesFor } from "@/lib/redis-reply";

/**
 * Pictures let in through the picture door (app/api/store/image/upload) and
 * not put on anything yet.
 *
 * A picture's name is chosen by the browser and the routes that put one on a
 * product, a link or a page only check that it sits in the store's own picture
 * folder. That folder is shared by every picture of the store, so a name the
 * browser sends may be the picture of another product, link or page. When
 * putting one on fails, the file may be deleted only when this very request
 * took it from this list and the file was stored after the door wrote it down
 * (dropTakenPictures): the door notes each name it signs for, only while no
 * file has that name, and the first route that tries to put it on anything
 * takes it off, whether that succeeds or not. A picture already on something
 * was taken then (or signed before this list existed, and never written
 * down), so a failed request naming it deletes nothing. Unknown is kept: a
 * file left behind costs storage, a picture deleted from under a product
 * costs the creator's page.
 *
 * The same note is what lets a new name onto a record at all (4 November
 * 2026, after a review proved that a picture put on a second record was
 * deleted with it): a product's or a link's picture, and a page's new one,
 * must be taken from this list by the request that puts it on, or be that
 * record's own already. A name another record shows, a buyer's review photo
 * or an email's picture was never noted (or was taken when it was put on),
 * so it is refused there, and taking it off the second record later can
 * never delete it. A picture put on before this rule stays where it is shown
 * and can still be kept or replaced there.
 *
 * One list per store's picture folder, so one store's doors never push out
 * another's. Notes older than PICTURE_DOOR_SECONDS, and past the newest
 * PICTURE_DOOR_MAX of the store, are dropped as new ones come in, and the list
 * itself expires a window after its last note; a dropped or stale note is
 * never taken, so its file is never deleted by a failure (it costs storage, at
 * most MAX_IMAGE_BYTES in lib/product-image.ts), never deleted wrongly.
 */
export const PICTURE_DOOR_SECONDS = 24 * 60 * 60;
/** The most notes a store keeps, newest first: past it the oldest go, and their files are kept, not deleted. */
export const PICTURE_DOOR_MAX = 1_000;

/** A picture's path is images/<folder>/<file>; its store's list is named by the folder. */
function doorsKey(path: string): string | null {
  const parts = path.split("/");
  return parts.length === 3 && parts[0] === "images" && /^[0-9a-f]{24}$/.test(parts[1]) ? `nl:pictures:doors:${parts[1]}` : null;
}

/**
 * Writes down a picture the door just signed for, in milliseconds; old notes are dropped with it. False when it
 * could not be written: such an upload could never be put on anything, so the door is not opened for it.
 */
export async function notePictureDoor(path: string, now = Date.now()): Promise<boolean> {
  const key = doorsKey(path);
  if (!key || !isRedisConfigured()) return false;
  const replies = repliesFor(await redisPipeline([
    ["ZREMRANGEBYSCORE", key, 0, now - PICTURE_DOOR_SECONDS * 1000],
    ["ZADD", key, now, path],
    ["ZREMRANGEBYRANK", key, 0, -(PICTURE_DOOR_MAX + 1)],
    ["EXPIRE", key, PICTURE_DOOR_SECONDS],
  ]), 4);
  // Noted only on its whole acknowledgement (Codex P on #2156): a count for each trim, 0 or 1 for the add, and 1
  // for the expiry the add made possible. Anything else is not a note, and the upload is not opened.
  if (!replies) return false;
  const [trimmed, added, kept, expires] = replies.map(countOf);
  return trimmed !== null && (added === 0 || added === 1) && kept !== null && expires === 1;
}

/**
 * Takes each of these pictures off its store's list, and returns those this
 * call took, with when the door signed for each (ms): the ones let in through
 * the door within PICTURE_DOOR_SECONDS that nothing had tried to put on yet.
 * A stale note is taken off but not returned.
 *
 * When the take cannot be confirmed (the read or the removal failed, or its
 * answer was lost), this throws, and every caller refuses with server_error
 * before it writes or deletes anything (4 November 2026, after a review
 * proved that a swallowed failure here let a picture go on a product with
 * its note still on the list, so a later refused request naming it took the
 * note and deleted the product's picture). Nothing is written, so a note
 * still there is on a picture nothing shows, and the creator's retry finds
 * it; a removal that ran with its answer lost leaves a file nothing shows,
 * kept (storage, never a picture deleted from under a record).
 */
export async function takePictureDoor(paths: string[], now = Date.now()): Promise<Map<string, number>> {
  const unique = [...new Set(paths.filter((path) => typeof path === "string" && doorsKey(path) !== null))];
  const taken = new Map<string, number>();
  if (unique.length === 0 || !isRedisConfigured()) return taken;
  const answers = await redisPipeline(unique.flatMap((path) => {
    const key = doorsKey(path) as string;
    return [["ZSCORE", key, path], ["ZREM", key, path]];
  }));
  if (!Array.isArray(answers) || answers.length !== 2 * unique.length) throw new Error("could not confirm the pictures taken from the door");
  // Each reply only in its exact shape (CX-123, rule 24): ZREM the whole number 0 or 1, ZSCORE null or a score (a
  // number, or the numeric string the REST API sends). Anything else is unknown and throws, never "taken".
  unique.forEach((path, i) => {
    // Read exactly (Codex P on #2156): the score is absent (null) or a number Redis wrote, the removal an exact 0 or
    // 1; anything else is not a confirmed take, and throws as an unconfirmed take does.
    const score = answers[2 * i];
    const removed = countOf(answers[2 * i + 1]);
    if (removed !== 0 && removed !== 1) throw new UnknownReplyError("taking a picture from the door: ZREM");
    if (score !== null && !(typeof score === "number" || (typeof score === "string" && /^\d{1,16}(\.\d+)?$/.test(score)))) {
      throw new UnknownReplyError("taking a picture from the door: ZSCORE");
    }
    const at = score === null ? NaN : Number(score);
    const fresh = Number.isFinite(at) && at > 0 && at >= now - PICTURE_DOOR_SECONDS * 1000;
    if (removed === 1 && fresh) taken.set(path, at);
  });
  return taken;
}

/**
 * Deletes those of these pictures that this request took from the door and
 * that were stored strictly after the door noted them. The door notes a name
 * only while no file has it, and an upload can never write over a file; the
 * time read here is a second check that a file stored before its note (a door
 * asked again for somebody's picture) is kept. Anything that cannot be read is
 * kept. Best effort: nothing here throws.
 */
export async function dropTakenPictures(taken: Map<string, number>, paths: string[]): Promise<void> {
  const ours: string[] = [];
  for (const path of new Set(paths)) {
    const noted = taken.get(path);
    if (noted === undefined) continue;
    const stored = await head(path).then((found) => new Date(found.uploadedAt).getTime(), () => NaN);
    if (Number.isFinite(stored) && stored > noted) ours.push(path);
  }
  if (ours.length) await del(ours).catch(() => {});
}

/**
 * Whether a note was put back on the door once already (returnToDoor): its time carries half a millisecond. A picture
 * taken with such a note is checked again only paid for as a studio request (lib/picture-check.ts pictureChecker).
 */
export const putBackOnce = (noted: number): boolean => !Number.isInteger(noted);

/**
 * Puts pictures this request took from the door back on it, each at the time given (ms), after a check of the file
 * did not finish (Claude 2 on #2843, 6750890970): the file is kept, and a later save finds the picture and checks it
 * again. Only a path with a door list; best effort, nothing here throws (a note not put back leaves a file nothing
 * shows, kept: storage, never a picture deleted).
 */
export async function returnToDoor(entries: ReadonlyArray<readonly [string, number]>): Promise<void> {
  const commands: (string | number)[][] = [];
  for (const [path, at] of entries) {
    const key = doorsKey(path);
    if (!key || !Number.isFinite(at) || at <= 0) continue;
    commands.push(["ZADD", key, at, path], ["EXPIRE", key, PICTURE_DOOR_SECONDS]);
  }
  if (commands.length && isRedisConfigured()) await redisPipeline(commands).catch(() => {});
}

lib/sales-page-store.ts.content:
/**
 * Where a product's page of blocks is kept (lib/sales-page.ts says what it
 * is): one small record per product, under the store's statsId, like the
 * long description.
 *
 * The store's own record says only whether a product has a page (its `page`
 * flag), so the store page — read on every visit — never carries thirty
 * blocks of somebody else's product. The page is read only by the product's
 * own page, the page after a free sign-up and the studio.
 *
 *   nl:product:page:<statsId>:<productId>  -> the page, as JSON
 *   nl:product:pics:<statsId>              -> hash: picture path -> the product whose page shows it
 *   nl:sblock:uses:<statsId>:<section>     -> set: the pages carrying a saved section (lib/saved-block-store.ts),
 *                                             kept with every save
 *   nl:product:pages:<statsId>:<productId> -> list: the page as it was before each of its last
 *                                             five saves, newest first, as "<ms>\n<json>"; kept
 *                                             as long as the page (since 18 October 2026: until
 *                                             then forgotten 30 days after the last save)
 *   nl:product:landing:<statsId>:<productId> -> its campaigns' landing words (lib/campaign-landing-store.ts),
 *                                             forgotten with the page
 *
 * A page and its earlier versions take room in the store's data room
 * (lib/store-data.ts) before they are written, one slot for the page (with
 * its pictures' and sections' entries) and one for its versions, so a save
 * that does not fit is refused and the page stays as it was.
 *
 * A page's pictures are files in the store's picture folder
 * (lib/product-image.ts). Each belongs to the one page that first showed it,
 * written down in the hash, so that taking a picture off a page — or removing
 * the product — deletes a file no other page is showing, and never one that
 * another page is.
 */
import { isRedisConfigured, redisPipeline } from "@/lib/redis";
import { dropLandings } from "@/lib/campaign-landing-store";
import { UnknownReplyError, repliesFor } from "@/lib/redis-reply";
import { takePictureDoor } from "@/lib/picture-door";
import { EMPTY_PAGE, MAX_STORED_PAGE_BYTES, type SalesPage, parsePage, picturePaths } from "@/lib/sales-page";
import { sectionsOn } from "@/lib/saved-blocks";
import { usesCommands } from "@/lib/saved-block-store";
import { type DataChange, type DataStore, giveData, needData, noteData } from "@/lib/store-data";
import { ENTRY_BYTES, dataBytes } from "@/lib/store-data-rules";

const pageKey = (statsId: string, productId: string) => `nl:product:page:${statsId}:${productId}`;
const picsKey = (statsId: string) => `nl:product:pics:${statsId}`;
const versionsKey = (statsId: string, productId: string) => `nl:product:pages:${statsId}:${productId}`;

/** How many earlier versions of a page are kept. */
export const MAX_VERSIONS = 5;

const PAGE_SLOT = (productId: string) => `pg:${productId}`;
const VERSIONS_SLOT = (productId: string) => `pv:${productId}`;

/** What a page counts for in the store's data room: its record, and an entry for each of its pictures and saved sections. */
function pageBytes(page: SalesPage, json: string): number {
  return dataBytes([json], 1) + (picturePaths(page).length + sectionsOn(page).length) * ENTRY_BYTES + (page.test ? AB_RECORD_BYTES : 0);
}

/**
 * What a headline test's counts weigh at the most (lib/headline-test.ts):
 * eleven fields and the key. Counted with the page while the test is on it,
 * and for TEST_KEPT_DAYS once it is taken off or replaced, which is how long
 * its counts can still be written to and kept: a checkout opened from it is
 * counted for up to forty days, and its record is kept 400 after that.
 */
export const AB_RECORD_BYTES = 1_024;
const TEST_KEPT_DAYS = 440;

/** The id of the headline test a stored record carries, or "". */
function testOfRecord(raw: unknown): string {
  if (typeof raw !== "string" || !raw || raw.length > MAX_STORED_PAGE_BYTES) return "";
  try {
    return parsePage(JSON.parse(raw)).test?.id ?? "";
  } catch {
    return "";
  }
}

/** The counts of a test taken off a page, kept by themselves until they expire. */
const endedTest = (now: number) => ({ until: now + TEST_KEPT_DAYS * 86_400_000, bytes: AB_RECORD_BYTES });

/**
 * Says these pictures are this product's page's. Returns the ones that are
 * not: already shown on another product's page, which keeps them.
 */
export async function claimPictures(statsId: string, productId: string, paths: string[]): Promise<string[]> {
  if (paths.length === 0 || !isRedisConfigured()) return [];
  await redisPipeline(paths.map((path) => ["HSETNX", picsKey(statsId), path, productId]));
  const [owners] = await redisPipeline([["HMGET", picsKey(statsId), ...paths]]);
  const list = Array.isArray(owners) ? owners : [];
  return paths.filter((_, i) => list[i] !== productId);
}

/**
 * Says these pictures, new on this page, are this page's, and returns whether
 * every one of them may be: each has to be let in through the picture door
 * for this very save (lib/picture-door.ts, taken here) or be written down as
 * this page's already (a save tried again after a failure).
 *
 * The store's pictures share one folder, and this registry lists only the
 * pages' pictures: a product's, a link's, a buyer's review photo or an
 * email's picture sit in the same folder unlisted. So a name that is neither
 * fresh from the door nor this page's is refused, never claimed; otherwise
 * taking it off this page later would delete a file another record shows.
 * Another page's picture is refused as before. A picture from before the door
 * existed stays on the page that shows it: it is never new there.
 *
 * Those taken from the door are claimed even when another is refused, so the
 * creator's save tried again still finds them; nothing is deleted here.
 * `check` is given the ones this call took from the door, before any of them is
 * written down as this page's, and answers which are pictures (MR audit gap 1:
 * each is asked about in the file store once, when taken). Only those become
 * the page's, so being this page's always means checked (Codex Z on #2843): a
 * take whose check never finished, a lost reply or a crash, leaves a picture
 * neither in the door nor owned, refused by every later save, never put on
 * unchecked.
 * A take from the door that cannot be confirmed throws (takePictureDoor), so
 * the page is refused with server_error before it is written.
 */
export async function claimNewPictures(
  statsId: string, pageId: string, paths: string[], check?: (taken: ReadonlyMap<string, number>) => Promise<{ good: string[]; unknown: string[] }>,
): Promise<boolean> {
  const unique = [...new Set(paths)];
  if (unique.length === 0) return true;
  // Not known is ours to say, never "add the picture again" (Claude 4 on #2156): it throws, and the route answers
  // server_error before anything is written.
  if (!isRedisConfigured()) throw new UnknownReplyError("page pictures: no database");
  const [owners] = await redisPipeline([["HMGET", picsKey(statsId), ...unique]]);
  if (!Array.isArray(owners) || owners.length !== unique.length) throw new UnknownReplyError("page pictures: HMGET");
  const list = owners;
  // An owner is a name or nobody (null); any other answer is unknown, and throws as the read above does.
  if (list.some((owner) => owner !== null && typeof owner !== "string")) throw new UnknownReplyError("page pictures: an owner");
  if (unique.some((_, i) => typeof list[i] === "string" && list[i] !== "" && list[i] !== pageId)) return false;
  const unclaimed = unique.filter((_, i) => list[i] !== pageId);
  const taken = await takePictureDoor(unclaimed);
  const tookNow = unclaimed.filter((path) => taken.has(path));
  // Checked before they are written down as this page's, and only those that are pictures are (Codex Z on #2843).
  // A check that did not finish puts its picture back on the door (lib/picture-check.ts), and the save throws, so the
  // route answers server_error and the creator's save tried again checks it again (Claude 2 on #2843, 6750890970); the
  // pictures that passed are written down first, so that save does not check them again.
  const checks = check && tookNow.length ? await check(new Map(tookNow.map((path) => [path, taken.get(path) as number]))) : { good: tookNow, unknown: [] };
  const checked = new Set(checks.good);
  const fresh = tookNow.filter((path) => checked.has(path));
  let held = true;
  if (fresh.length) {
    await redisPipeline(fresh.map((path) => ["HSETNX", picsKey(statsId), path, pageId]));
    const [after] = await redisPipeline([["HMGET", picsKey(statsId), ...fresh]]);
    const now = Array.isArray(after) ? after : [];
    held = !fresh.some((_, i) => now[i] !== pageId);
  }
  if (checks.unknown.length) throw new Error("page pictures: a check of the file store did not finish");
  return held && fresh.length === unclaimed.length;
}

/**
 * Lets go of pictures a page no longer shows. Returns the files to delete:
 * only those this product's page was the one showing.
 */
export async function releasePictures(statsId: string, productId: string, paths: string[]): Promise<string[]> {
  if (paths.length === 0 || !isRedisConfigured()) return [];
  const [owners] = await redisPipeline([["HMGET", picsKey(statsId), ...paths]]);
  const list = Array.isArray(owners) ? owners : [];
  const mine = paths.filter((_, i) => list[i] === productId);
  if (mine.length) await redisPipeline([["HDEL", picsKey(statsId), ...mine]]);
  return mine;
}

/**
 * A product's page, or the empty page when Redis confirms none is kept (a GET
 * that answers null). Any other answer (no reply, more than one, a slot that
 * is not a text, a kept record that is not a page) throws UnknownReplyError,
 * so nothing is ever decided from an empty page that was not (CX-123 rule 24;
 * Codex T's proof, C4-20261106-2610-C6-153). A failed request throws as before.
 */
export async function readPage(statsId: string | null, productId: string): Promise<SalesPage> {
  if (!statsId || !isRedisConfigured()) return { ...EMPTY_PAGE, blocks: [] };
  const replies = repliesFor(await redisPipeline([["GET", pageKey(statsId, productId)]]), 1);
  if (!replies) throw new UnknownReplyError("a page read");
  return pageOf(replies[0]);
}

/** A kept page from its GET or MGET slot: null is "none kept", a page's JSON is the page, anything else throws. */
function pageOf(raw: unknown): SalesPage {
  if (raw === null) return { ...EMPTY_PAGE, blocks: [] };
  if (typeof raw !== "string" || !raw || raw.length > MAX_STORED_PAGE_BYTES) throw new UnknownReplyError("a kept page");
  try {
    return pageRecordExact(raw, "a kept page");
  } catch {
    throw new UnknownReplyError("a kept page");
  }
}

/**
 * Values of many keys, a hundred at a command (MGET): what the whole export
 * reads (lib/store-export.ts). Each command must answer exactly one list with
 * one slot per key asked, or the whole read throws UnknownReplyError.
 */
async function readMany(keys: string[]): Promise<unknown[]> {
  const out: unknown[] = [];
  for (let i = 0; i < keys.length; i += 100) {
    const asked = keys.slice(i, i + 100);
    const replies = repliesFor(await redisPipeline([["MGET", ...asked]]), 1);
    const values = replies ? repliesFor(replies[0], asked.length) : null;
    if (!values) throw new UnknownReplyError("a batch of page reads");
    out.push(...values);
  }
  return out;
}

/** The pages of many products, in their order, a hundred at a command; throws like readPage when any answer is unknown. */
export async function readPages(statsId: string | null, productIds: string[]): Promise<SalesPage[]> {
  if (!statsId || !isRedisConfigured()) return productIds.map(() => ({ ...EMPTY_PAGE, blocks: [] }));
  return (await readMany(productIds.map((id) => pageKey(statsId, id)))).map(pageOf);
}

/** Whether a page has anything the product's page should draw instead of its plain layout. */
export function hasBlocks(page: SalesPage): boolean {
  return page.blocks.length > 0;
}

/**
 * Writes a page, or forgets it when it has no blocks and nothing else set.
 * Its room is taken first (DataRoomError when it does not fit); `always`
 * counts it whatever it comes to, for what the store already had.
 */
export async function writePage(statsId: string, productId: string, page: SalesPage, room: DataStore, always = false): Promise<void> {
  const empty = page.blocks.length === 0 && !page.seoTitle && !page.seoDescription && !page.next;
  const json = JSON.stringify(page);
  const key = versionsKey(statsId, productId);
  const [before, kept, oldest] = await redisPipeline([["GET", pageKey(statsId, productId)], ["LLEN", key], ["LINDEX", key, -1]]);
  const commands: (string | number)[][] = [empty ? ["DEL", pageKey(statsId, productId)] : ["SET", pageKey(statsId, productId), json]];
  // What the page was, kept so a save can be undone from the studio. The
  // version pushed takes room; the oldest one it pushes out gives its own back.
  let versions = 0;
  if (typeof before === "string" && before && before !== json && before.length <= MAX_STORED_PAGE_BYTES) {
    const entry = `${Date.now()}\n${before}`;
    versions = dataBytes([entry], 1) - (Number(kept) >= MAX_VERSIONS && typeof oldest === "string" ? dataBytes([oldest], 1) : 0);
    commands.push(["LPUSH", key, entry], ["LTRIM", key, 0, MAX_VERSIONS - 1], ["PERSIST", key]);
  }
  const ended = testOfRecord(before);
  const changes: DataChange[] = [{ slot: PAGE_SLOT(productId), bytes: empty ? 0 : pageBytes(page, json), set: true }, { slot: VERSIONS_SLOT(productId), bytes: versions }];
  if (ended && (empty || page.test?.id !== ended)) changes.push(endedTest(Date.now()));
  if (always) await noteData(room, changes);
  else await needData(room, changes);
  // Which saved sections the page carries, before and after (lib/saved-blocks.ts).
  commands.push(...usesCommands(statsId, productId, sectionsOfRecord(before), empty ? [] : sectionsOn(page)));
  await redisPipeline(commands);
}

/** The saved sections a stored record carries; none when it cannot be read. */
function sectionsOfRecord(raw: unknown): string[] {
  if (typeof raw !== "string" || !raw || raw.length > MAX_STORED_PAGE_BYTES) return [];
  try {
    return sectionsOn(parsePage(JSON.parse(raw)));
  } catch {
    return [];
  }
}

export type PageVersion = { at: number; page: SalesPage };

/** The page as it was before each of its last saves, newest first. */
/**
 * How many versions of a page are kept, read exactly (LLEN) and at most the
 * MAX_VERSIONS readVersions reads, so a reading of them is paid for before it
 * is made (lib/mcp-tools.ts); null when Redis answered in another shape.
 */
export async function countVersions(statsId: string | null, productId: string): Promise<number | null> {
  if (!statsId || !isRedisConfigured()) return 0;
  const replies: unknown = await redisPipeline([["LLEN", versionsKey(statsId, productId)]]);
  if (!Array.isArray(replies) || replies.length !== 1) return null;
  const n = replies[0];
  return typeof n === "number" && Number.isSafeInteger(n) && n >= 0 ? Math.min(n, MAX_VERSIONS) : null;
}

/**
 * A product's page exactly as kept, for a reader that must never take an
 * answer it does not know for an empty page (the MCP tools): null when no
 * page is kept; throws when Redis's answer is not exactly one text or null,
 * or when the kept record is not a page.
 */
export async function readPageExact(statsId: string, productId: string): Promise<{ page: SalesPage | null; bytes: number }> {
  if (!isRedisConfigured()) throw new Error("the page could not be read");
  const reply: unknown = await redisPipeline([["GET", pageKey(statsId, productId)]]);
  if (!Array.isArray(reply) || reply.length !== 1) throw new Error("the page could not be read");
  const raw = reply[0];
  if (raw === null) return { page: null, bytes: 0 };
  if (typeof raw !== "string" || !raw || raw.length > MAX_STORED_PAGE_BYTES) throw new Error("the page could not be read");
  return { page: pageRecordExact(raw, "the page could not be read"), bytes: Buffer.byteLength(raw, "utf8") };
}

/** A kept page record decoded: an object with its list of blocks, before the forgiving normalization; anything else throws (Codex J on #1821: JSON null or [] is not an empty page). */
function pageRecordExact(json: string, what: string): SalesPage {
  let decoded: unknown;
  try {
    decoded = JSON.parse(json);
  } catch {
    throw new Error(what);
  }
  if (typeof decoded !== "object" || decoded === null || Array.isArray(decoded) || !Array.isArray((decoded as { blocks?: unknown }).blocks)) throw new Error(what);
  try {
    return parsePage(decoded);
  } catch {
    throw new Error(what);
  }
}

/**
 * A page's kept versions exactly as kept, newest first, for a reader that must
 * never take an answer it does not know for "no versions" (the MCP tools):
 * throws when Redis's answer is not exactly one list of texts, or when a kept
 * version is not one, so nothing is left out unsaid.
 */
export async function readVersionsExact(statsId: string, productId: string): Promise<{ versions: PageVersion[]; bytes: number }> {
  if (!isRedisConfigured()) throw new Error("the page's versions could not be read");
  const reply: unknown = await redisPipeline([["LRANGE", versionsKey(statsId, productId), 0, MAX_VERSIONS - 1]]);
  if (!Array.isArray(reply) || reply.length !== 1 || !Array.isArray(reply[0])) throw new Error("the page's versions could not be read");
  const versions: PageVersion[] = [];
  let bytes = 0;
  for (const entry of reply[0] as unknown[]) {
    if (typeof entry !== "string") throw new Error("the page's versions could not be read");
    bytes += Buffer.byteLength(entry, "utf8");
    const cut = entry.indexOf("\n");
    const at = Number(entry.slice(0, cut));
    if (cut < 1 || !Number.isFinite(at)) throw new Error("the page's versions could not be read");
    versions.push({ at, page: pageRecordExact(entry.slice(cut + 1), "the page's versions could not be read") });
  }
  return { versions, bytes };
}

export async function readVersions(statsId: string | null, productId: string): Promise<PageVersion[]> {
  if (!statsId || !isRedisConfigured()) return [];
  const [list] = await redisPipeline([["LRANGE", versionsKey(statsId, productId), 0, MAX_VERSIONS - 1]]);
  if (!Array.isArray(list)) return [];
  const out: PageVersion[] = [];
  for (const entry of list) {
    if (typeof entry !== "string") continue;
    const cut = entry.indexOf("\n");
    const at = Number(entry.slice(0, cut));
    if (cut < 1 || !Number.isFinite(at)) continue;
    try {
      out.push({ at, page: parsePage(JSON.parse(entry.slice(cut + 1))) });
    } catch {
      // A version that cannot be read is left out, never shown half.
    }
  }
  return out;
}

/**
 * A page was dropped, but not all it held could be confirmed gone (its campaigns' landings): what is left stays
 * counted in the store's room. `pictures` are still the files the page was the one showing, released and to delete.
 */
export class PageDropIncomplete extends Error {
  constructor(readonly pictures: string[], readonly kept: unknown) {
    super("The page was deleted, but some of its records could not be confirmed gone; they stay counted until they are.");
  }
}

/**
 * What a route deletes after dropPage failed: the pictures it released when it got that far (PageDropIncomplete),
 * none otherwise; and the failure is said in the log, never taken for a page dropped whole (Codex G2, #1947).
 */
export function picturesOfFailedDrop(error: unknown): string[] {
  console.error("a removed page's records could not all be confirmed gone; what is left stays counted in the store's room", error);
  return error instanceof PageDropIncomplete ? error.pictures : [];
}

/**
 * Forgets the page of a product that is gone, and gives back its room. Returns the picture files it was the one
 * showing, to delete. When its campaigns' landings cannot be confirmed gone, the rest is still done and it throws
 * PageDropIncomplete with those pictures: never a page said dropped whole while its landings may be kept.
 */
export async function dropPage(statsId: string | null, productId: string, room: DataStore): Promise<string[]> {
  if (!statsId || !isRedisConfigured()) return [];
  const held = await readPage(statsId, productId).catch(() => ({ ...EMPTY_PAGE, blocks: [] }));
  const shown = picturePaths(held);
  // A failed page step does not keep its campaigns' landings: they are still tried below, and the failure is said
  // after them (Claude 5 on #1947). The page's room is given back only once its records are confirmed sent.
  let pageFailed: { error: unknown } | null = null;
  try {
    await redisPipeline([["DEL", pageKey(statsId, productId), versionsKey(statsId, productId)], ...usesCommands(statsId, productId, sectionsOn(held), [])]);
    await giveData(room, [{ slot: PAGE_SLOT(productId), bytes: 0, set: true }, { slot: VERSIONS_SLOT(productId), bytes: 0, set: true }]);
  } catch (error) {
    pageFailed = { error };
  }
  // Its campaigns' landings are its page's words: they go with it (lib/campaign-landing-store.ts). Their room is
  // given back only by the step that drops them, so one not confirmed stays counted.
  const landings = await dropLandings(statsId, productId, room).then(() => null, (error: unknown) => ({ error }));
  if (pageFailed) throw new PageDropIncomplete([], pageFailed.error);
  // A test's counts stay until they expire, counted on their own.
  if (held.test) await noteData(room, [endedTest(Date.now())]);
  const pictures = await releasePictures(statsId, productId, shown);
  if (landings) throw new PageDropIncomplete(pictures, landings.error);
  return pictures;
}

app/api/store/page/route.ts.content:
import { fastMoneyOnPage } from "@/lib/terms-check-rules";
import { pageWords } from "@/lib/page-translate";
import type { NextRequest } from "next/server";
import { StoreFullError, imageFolder, isFree, setProductPage } from "@/lib/store";
import { productIdFor, readListing } from "@/lib/catalog";
import { guardStoreWrite, text } from "@/lib/store-request";
import { EMPTY_PAGE, MAX_BLOCKS, type SalesPage, copyOfPage, declareMeasure, oversized, pageProblem, parsePage, picturePaths } from "@/lib/sales-page";
import { countStudio, jsonAccess, refusedJson } from "@/lib/studio-route";
import { lockedFor } from "@/lib/two-step";
import { claimNewPictures, readPage, releasePictures, writePage } from "@/lib/sales-page-store";
import { del } from "@/lib/blob";
import { imagePaths, ownsImagePath } from "@/lib/product-image";
import { pictureChecker } from "@/lib/picture-check";

/**
 * Thirty full blocks as JSON, twice — a page and a second version tested
 * against it — with room to spare; each is held to MAX_PAGE_BYTES.
 */
const MAX_BODY_BYTES = 420_000;

/** A page read whose answer is not known: refused before anything is written (lib/studio-messages.ts page_unread). */
const unread = () => Response.json({ ok: false, error: "page_unread" }, { status: 503, headers: { "Cache-Control": "private, no-store" } });

/**
 * Saves a product's page of blocks (lib/sales-page.ts), or clears it.
 *
 * `{ id, page: { blocks, seoTitle, seoDescription, next, test, variant } }`, or
 * `{ id, page: null }` for the plain page again. Every rule the product's
 * page applies is applied here first, and a page that would be saved
 * differently from how it was sent is refused with the reason, so the
 * studio never says "saved" about something it did not save.
 */
export async function POST(request: NextRequest) {
  // A product's page is part of the product (lib/team-roles.ts): owner, Admin, Editor.
  const guarded = await guardStoreWrite(request, "products", MAX_BODY_BYTES);
  if (!guarded.ok) return guarded.response;
  const body = guarded.body;
  const id = text(body.id, 40);
  if (!id || !("page" in body)) return Response.json({ ok: false, error: "unknown" }, { status: 400 });

  const store = guarded.store;
  const product = await readListing(store, id);
  if (!product) return Response.json({ ok: false, error: "unknown" }, { status: 400 });

  const raw = body.page && typeof body.page === "object" ? (body.page as Record<string, unknown>) : null;
  const page = raw ? parsePage(raw) : { ...EMPTY_PAGE, blocks: [] };
  if (raw) {
    if (Array.isArray(raw.blocks) && raw.blocks.length > MAX_BLOCKS) return Response.json({ ok: false, error: "too_many" }, { status: 400 });
    const problem = pageProblem(raw, page);
    if (problem) return Response.json({ ok: false, error: problem }, { status: 400 });
    // A form is asked on the store's own pages, where it can lead a funnel on; a product's page has its own checkout.
    if (page.blocks.some((block) => block.kind === "form")) return Response.json({ ok: false, error: "kind" }, { status: 400 });
    // A booking block is kept and drawn but not offered yet (552 [BB1] unit 1): nothing saves one, in either version,
    // until its picker and its call chooser exist, so a hand-made request cannot put any id on a page.
    if ([...page.blocks, ...(page.variant?.blocks ?? [])].some((block) => block.kind === "booking")) {
      return Response.json({ ok: false, error: "kind" }, { status: 400 });
    }
    if (oversized(page)) return Response.json({ ok: false, error: "too_big" }, { status: 400 });
    // What is shown after a free sign-up is another product of this store,
    // one that costs money; a paid product's page shows nothing after.
    const sentNext = typeof raw.next === "string" && raw.next ? raw.next : null;
    if (sentNext) {
      const next = await readListing(store, sentNext);
      if (!isFree(product) || !next || next.id === product.id || isFree(next)) {
        return Response.json({ ok: false, error: "next" }, { status: 400 });
      }
    }
  }

  // A page is on the store with its product: what the Terms forbid is refused while the product is published
  // (567 [GD1] (d), unit 2), with the passage, why and the fix; a draft's page may be saved, and is checked when
  // the product is published. A product that cannot be read was refused above.
  if (product.hidden !== true) {
    const refused = fastMoneyOnPage(pageWords(page));
    if (refused) return Response.json({ ok: false, error: "fast_money", passage: refused }, { status: 409 });
  }

  const has = page.blocks.length > 0 || page.seoTitle !== "" || page.seoDescription !== "" || page.next !== null;
  try {
    // The pictures on the page (lib/sales-page.ts, PicturesBlock). What the
    // browser says it uploaded is never taken at face value: each new one
    // has to be a file in this store's own picture folder that really is a
    // picture, not the product's own picture under another name, and not
    // one another product's page is already showing.
    // A page whose read is not known is never taken for an empty one: nothing is claimed, released or written from it.
    let stored: SalesPage | null = null;
    if (store.statsId && product.page) {
      try {
        stored = await readPage(store.statsId, id);
      } catch (error) {
        console.error("reading a product page before saving it failed", error);
        return unread();
      }
    }
    const before = stored ? picturePaths(stored) : [];
    const shown = picturePaths(page);
    // A picture taken off the page is deleted for good: not from a session let in without its second step (lib/two-step.ts).
    if (before.some((path) => !shown.includes(path)) && (await lockedFor(request, "products", "replace"))) return refusedJson("locked");
    const fresh = shown.filter((path) => !before.includes(path));
    if (fresh.length > 0) {
      if (!store.statsId) return Response.json({ ok: false, error: "server_error" }, { status: 500 });
      const folder = await imageFolder(guarded.ref);
      const own = new Set(imagePaths(product.image));
      if (fresh.some((path) => !ownsImagePath(path, folder) || own.has(path))) {
        return Response.json({ ok: false, error: "pictures" }, { status: 400 });
      }
      // Each new one fresh from the picture door or already this page's, never another record's picture from the
      // shared folder, so taking it off later deletes only this page's own (lib/sales-page-store.ts, claimNewPictures).
      // Only those this save takes from the door are checked in the file store, and once (MR audit gap 1): one taken
      // by an earlier save was checked then, so a save tried again never asks Blob about the same picture twice.
      if (!(await claimNewPictures(store.statsId, id, fresh, pictureChecker(async (units) => (await countStudio(store, "products", units)).ok)))) {
        return Response.json({ ok: false, error: "pictures" }, { status: 400 });
      }
    }

    const marked = await setProductPage(guarded.ref, id, has);
    if (!marked.ok) return Response.json({ ok: false, error: marked.reason }, { status: 400 });
    if (!marked.store.statsId) return Response.json({ ok: false, error: "server_error" }, { status: 500 });
    // A running test declares, once, the measure it is decided by (lib/headline-test-rules.ts, rule 2).
    const saved = declareMeasure(page, stored, isFree(product) ? "checkouts" : "money");
    await writePage(marked.store.statsId, id, saved, marked.store);
    // A picture taken off the page is deleted, best effort and only after the
    // page that no longer shows it is written.
    const gone = await releasePictures(marked.store.statsId, id, before.filter((path) => !shown.includes(path))).catch(() => [] as string[]);
    if (gone.length > 0) {
      await del(gone).catch((error: unknown) => console.error("could not delete pictures taken off a page", error));
    }
    // The page as it was kept, so the editor shows exactly that without starting over.
    return Response.json({ ok: true, blocks: saved.blocks.length, page: saved });
  } catch (error) {
    if (error instanceof StoreFullError) return Response.json({ ok: false, error: "store_full" }, { status: 409 });
    console.error("saving a product page failed", error);
    return Response.json({ ok: false, error: "server_error" }, { status: 500 });
  }
}

/**
 * Another product's page of this store, to start a page from: `?id=<product>`.
 * Its blocks with fresh ids and without its pictures (lib/sales-page.ts,
 * copyOfPage); nothing is saved here.
 */
export async function GET(request: NextRequest) {
  const access = await jsonAccess(request, "products");
  if (access instanceof Response) return access;
  const id = (request.nextUrl.searchParams.get("id") ?? "").slice(0, 40);
  const store = access.store;
  if (!store || !id || productIdFor(store, id) !== id) return Response.json({ ok: false, error: "unknown" }, { status: 404 });
  try {
    const copy = copyOfPage(await readPage(store.statsId, id));
    return Response.json({ ok: true, ...copy }, { headers: { "Cache-Control": "private, no-store" } });
  } catch (error) {
    // Never a copy started from an empty page that was not.
    console.error("reading a page to copy failed", error);
    return unread();
  }
}

